{"qas": [
  {"question": "According to arXiv 2505.08133, what challenge does USAID face in AI grantmaking, and how does the 2022 AI Training Act relate to grant specialists?", "answer": "USAID highlights AI risks and recommends fairness resources, but the 2022 AI Training Act does not explicitly cover grant specialists, limiting upskilling.", "evidence": [{"page": 7, "quote": "USAID also includes links to resources on fairness and AI, recommending applicants consider those materials in order to submit a competitive proposal."}, {"page": 8, "quote": "the 2022 AI Training Act, for example, does not explicitly cover grant specialists [12]."}]},
  {"question": "What two main types of guardrails on AI use in federal grants does arXiv 2505.08133 identify?", "answer": "The two main types are requirements to disclose AI use and discouragement or prohibition of AI use.", "evidence": [{"page": 7, "quote": "The conditions impose two kinds of guardrails: to disclose the use of AI and to discourage or prohibit AI use."}]},
  {"question": "In arXiv 2505.08133, which abbreviation stands for the Department of State?", "answer": "DOS stands for the Department of State.", "evidence": [{"page": 11, "quote": "| DOS            | Department of State                                |"}]},
  {"question": "Which federal agency's program restricts the use of generative AI for creating educational materials, and what tools are specifically banned, according to arXiv 2505.08133?", "answer": "The Library of Congress restricts generative AI use, banning tools like ChatGPT, BARD, Dall-E, MidJourney, and Stable Diffusion.", "evidence": [{"page": 7, "quote": "A Library of Congress program to help create educational materials to build student literacy restricts awardees from using generative AI to produce project materials, detailing examples of prohibited uses and listing example banned tools like ChatGPT, BARD, Dall-E, MidJourney, and Stable Diffusion."}]},
  {"question": "According to arXiv 2505.08133, why might federal grant spending records fail to mention AI even when AI is involved?", "answer": "Spending records are often brief or vague, and may use jargon or omit details, making it unclear if AI was funded.", "evidence": [{"page": 11, "quote": "spending records tend to be shorter and less descriptive. Though publicly available, spending records are often too short or vague to answer whether a grant funds an AI use."}]},
  {"question": "Which federal act requires grant spending records to be searchable on a single website, as discussed in arXiv 2505.08133?", "answer": "The Federal Funding Accountability and Transparency Act requires searchable grant spending records on USASpending.gov.", "evidence": [{"page": 11, "quote": "The Federal Funding Accountability and Transparency Act [5] requires grant spending records be searchable on a single website, which is USASpending.gov."}]}
]}
